# IN-MEMORY GRAPH
# ══════════════════════════════════════════════════════════════
_N  = {}  # id → {name,lat,lon}
_AD = {}  # id → [(neighbor,dist_nm)]
for r in _GN:
    i,name,lat,lon = r
    _N[i]  = {'name':name,'lat':lat,'lon':lon}
    _AD[i] = []
for r in _GE:
    f,t,d = r
    _AD[f].append((t,d)); _AD[t].append((f,d))

# ══════════════════════════════════════════════════════════════
# BACKGROUND INIT — land polygons + searoute fallback
# ══════════════════════════════════════════════════════════════
SR=None; SR_ERR=None; LAND=None; READY=False

def _init():
    global SR,SR_ERR,LAND,READY
    # Land polygons — equivalent to WVS quadtree for land/sea detection
    try:
        gdf  = gpd.read_file("https://naturalearth.s3.amazonaws.com/10m_physical/ne_10m_land.zip")
        LAND = gdf.geometry.union_all()
        print('[v14] Land polygons loaded ✅',flush=True)
    except Exception as e:
        print(f'[v14] Land WARNING: {e}',file=sys.stderr,flush=True)
    # searoute fallback for routes outside graph coverage
    try:
        import searoute as sr
        sr.searoute([2.35,48.85],[103.82,1.27],units='naut')
        SR=sr; print('[v14] searoute fallback ready ✅',flush=True)
    except Exception as e:
        SR_ERR=str(e); print(f'[v14] searoute unavailable: {e}',file=sys.stderr,flush=True)
    READY=True
    print(f'[v14] READY — {len(_N)} graph nodes, {len(_GE)} edges',flush=True)

threading.Thread(target=_init,daemon=True).start()

# ══════════════════════════════════════════════════════════════
# GEOMETRY
# ══════════════════════════════════════════════════════════════
def hav(lat1,lon1,lat2,lon2):
    R=3440.065
    a=(math.sin(math.radians(lat2-lat1)/2)**2+
       math.cos(math.radians(lat1))*math.cos(math.radians(lat2))*
       math.sin(math.radians(lon2-lon1)/2)**2)
    return R*2*math.asin(math.sqrt(max(0,a)))

def brg(lon1,lat1,lon2,lat2):
    dl=math.radians(lon2-lon1); la,lb=math.radians(lat1),math.radians(lat2)
    return(math.degrees(math.atan2(math.sin(dl)*math.cos(lb),
           math.cos(la)*math.sin(lb)-math.sin(la)*math.cos(lb)*math.cos(dl)))+360)%360

def xland(c1,c2):
    if LAND is None: return False
    try: return LineString([c1,c2]).intersects(LAND)
    except: return False

def any_xland(coords):
    return any(xland(coords[i],coords[i+1]) for i in range(len(coords)-1))

def rdp(coords,eps=1.5):
    if len(coords)<=2: return coords
    def pd(p,a,b):
        dx,dy=b[0]-a[0],b[1]-a[1]
        if dx==dy==0: return hav(p[1],p[0],a[1],a[0])
        t=max(0,min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy)))
        return hav(p[1],p[0],a[1]+t*dy,a[0]+t*dx)
    def _r(pts,e):
        if len(pts)<=2: return pts
        dm,idx=0,0
        for i in range(1,len(pts)-1):
            d=pd(pts[i],pts[0],pts[-1])
            if d>dm: dm,idx=d,i
        return _r(pts[:idx+1],e)[:-1]+_r(pts[idx:],e) if dm>e else [pts[0],pts[-1]]
    return _r(coords,eps)

# ══════════════════════════════════════════════════════════════
# A* ROUTING ON PORTTOPORT GRAPH
# ══════════════════════════════════════════════════════════════
def knn(lat,lon,k=5):
    return sorted([(hav(lat,lon,n['lat'],n['lon']),i) for i,n in _N.items()])[:k]

def astar(s,e):
    el,eln=_N[e]['lat'],_N[e]['lon']
    h=lambda n:hav(_N[n]['lat'],_N[n]['lon'],el,eln)
    g={i:float('inf') for i in _N}; g[s]=0; prev={}
    pq=[(h(s),0.0,s)]; vis=set()
    while pq:
        f,c,u=heapq.heappop(pq)
        if u in vis: continue
        vis.add(u)
        if u==e: break
        for v,w in _AD.get(u,[]):
            nc=c+w
            if nc<g[v]: g[v]=nc; prev[v]=u; heapq.heappush(pq,(nc+h(v),nc,v))
    if g[e]==float('inf'): return None,float('inf')
    path,cur=[],e
    while cur in prev: path.append(cur); cur=prev[cur]
    path.append(s); return list(reversed(path)),g[e]

def graph_route(flat,flon,tlat,tlon):
    fc=knn(flat,flon,5); tc=knn(tlat,tlon,5)
    best=(None,float('inf'),None,None)
    for d1,n1 in fc:
        for d2,n2 in tc:
            if n1==n2: continue
            path,nm=astar(n1,n2)
            if path and d1+nm+d2<best[1]: best=(path,d1+nm+d2,n1,n2)
    if not best[0]: return None,None,float('inf')
    path=best[0]
    # Build coords: origin → graph → destination
    coords=[[flon,flat]]
    for nid in path: nd=_N[nid]; coords.append([nd['lon'],nd['lat']])
    coords.append([tlon,tlat])
    return coords,path,best[1]

def sr_fallback(flat,flon,tlat,tlon):
    if SR is None: return [[flon,flat],[tlon,tlat]],0.0,'no-fallback'
    try:
        r=SR.searoute([flon,flat],[tlon,tlat],units='naut',append_orig_dest=True)
        return r.geometry['coordinates'],float(r.properties.get('length',0)),'searoute-fallback'
    except Exception as e:
        return [[flon,flat],[tlon,tlat]],0.0,f'error:{e}'

# ══════════════════════════════════════════════════════════════
# SAFETY CHECKS
# ══════════════════════════════════════════════════════════════
GEBCO='https://api.odb.ntu.edu.tw/gebco'
OVP  ='https://overpass-api.de/api/interpreter'
_DC={};_TC={}

def tss_check(coords,buf=0.3):
    if not coords: return []
    lons=[c[0] for c in coords]; lats=[c[1] for c in coords]
    s,n,w,e=round(min(lats)-buf,2),round(max(lats)+buf,2),round(min(lons)-buf,2),round(max(lons)+buf,2)
    k=f"{s}_{w}_{n}_{e}"
    if k in _TC: return _TC[k]
    q=(f'[out:json][timeout:20];'
       f'(way["seamark:type"="separation_lane"]({s},{w},{n},{e});'
       f'way["seamark:type"="separation_zone"]({s},{w},{n},{e});'
       f'relation["seamark:type"="traffic_separation_scheme"]({s},{w},{n},{e}););'
       f'out tags center;')
    zs=[]
    try:
        r=requests.post(OVP,data={'data':q},timeout=15)
        if r.status_code==200:
            for el in r.json().get('elements',[]):
                t=el.get('tags',{}); nm=t.get('seamark:name') or t.get('name') or 'TSS'
                if nm not in zs: zs.append(nm)
    except: pass
    _TC[k]=zs; return zs

def danger_check(coords,buf=2.0):
    DTYPE=['rock','wreck','obstruction','shoal','reef','underwater_rock','foul_ground','snag']
    lons=[c[0] for c in coords]; lats=[c[1] for c in coords]
    s,n,w,e=round(min(lats)-.1,2),round(max(lats)+.1,2),round(min(lons)-.1,2),round(max(lons)+.1,2)
    k=f"{s}_{w}_{n}_{e}"
    if k in _DC: dm=_DC[k]
    else:
        fi='\n'.join([f'  node["seamark:type"="{t}"]({s},{w},{n},{e});' for t in DTYPE])
        dm=[]
        try:
            r=requests.post(OVP,data={'data':f"[out:json][timeout:20];\n(\n{fi}\n);\nout body;"},timeout=15)
            if r.status_code==200:
                for el in r.json().get('elements',[]):
                    tags=el.get('tags',{}); dm.append({'type':tags.get('seamark:type','?'),'name':tags.get('name',''),'lon':el.get('lon'),'lat':el.get('lat')})
        except: pass
        _DC[k]=dm
    nb=[]
    for d in dm:
        dl,da=d.get('lon'),d.get('lat')
        if dl is None: continue
        md=min(hav(da,dl,c[1],c[0]) for c in coords)
        if md<buf: nb.append({**d,'nearest_nm':round(md,2)})
    return {'safe':not nb,'dangers':nb,'total':len(dm)}

def depth_check(coords,draft=10.0,safety=2.0):
    mr=draft+safety; pts=[]
    for i in range(len(coords)-1):
        c1,c2=coords[i],coords[i+1]; st=max(1,int(hav(c1[1],c1[0],c2[1],c2[0])/15))
        for s in range(st): t=s/st; pts.append((c1[0]+t*(c2[0]-c1[0]),c1[1]+t*(c2[1]-c1[1])))
    if coords: pts.append((coords[-1][0],coords[-1][1]))
    sh,dep=[],[]
    try:
        r=requests.get(f"{GEBCO}?lon={','.join(str(round(p[0],4)) for p in pts)}&lat={','.join(str(round(p[1],4)) for p in pts)}&mode=zonly",timeout=15)
        if r.status_code==200:
            data=r.json(); zs=data.get('z',[]) if isinstance(data,dict) else data
            for i,p in enumerate(pts):
                if i<len(zs) and zs[i] is not None:
                    wd=abs(zs[i]) if zs[i]<0 else 0; dep.append(wd)
                    if 0<wd<mr: sh.append({'lon':p[0],'lat':p[1],'depth':round(wd,1),'required':mr})
    except: pass
    return {'safe':not sh,'min_depth':round(min(dep),1) if dep else None,'shallow':sh,'checked':len(pts),'required':mr}

# ══════════════════════════════════════════════════════════════
# /route
# ══════════════════════════════════════════════════════════════
@app.route('/route')
def route_ep():
    try:
        flat=float(request.args['fromLat']); flon=float(request.args['fromLon'])
        tlat=float(request.args['toLat']);   tlon=float(request.args['toLon'])
        draft=float(request.args.get('draft',10.0))
        saf  =float(request.args.get('safety',2.0))
        eps  =float(request.args.get('simplify',1.5))
        do_depth  = request.args.get('depth','false').lower()=='true'
        do_danger = request.args.get('danger','true').lower()=='true'
        do_tss    = request.args.get('tss','true').lower()=='true'
    except (KeyError,ValueError) as ex:
        return jsonify({'error':f'Bad param: {ex}'}),400

    # Step 1: Graph A* routing
    coords,path,graph_nm = graph_route(flat,flon,tlat,tlon)
    method='graph-astar'

    # Step 2: Fallback if graph has no path
    if coords is None:
        coords,graph_nm,method = sr_fallback(flat,flon,tlat,tlon)
        path=[]

    # Step 3: Simplify (keep meaningful course changes)
    simp=rdp(coords,eps)

    # Step 4: Recalculate actual NM
    total_nm=sum(hav(simp[i][1],simp[i][0],simp[i+1][1],simp[i+1][0]) for i in range(len(simp)-1))

    # Step 5: Land cross check
    lc=any_xland(simp)

    # Step 6: Named waypoints on path
    named=[{'name':_N[nid]['name'],'lat':_N[nid]['lat'],'lon':_N[nid]['lon']}
           for nid in (path or []) if _N[nid]['name']]

    # Step 7: Optional safety checks
    tss  = tss_check(simp) if do_tss else []
    dng  = danger_check(simp) if do_danger else {'safe':True,'dangers':[],'total':0}
    dep  = depth_check(simp,draft,saf) if do_depth else {'safe':True,'shallow':[],'checked':0,'required':draft+saf}

    # Step 8: Warnings
    warns=[]
    if lc: warns.append('🚨 Route crosses land — check coverage or add manual WPs')
    for z in tss: warns.append(f'🚢 TSS: {z} — verify correct separation lane')
    for sp in dep.get('shallow',[]): warns.append(f"⚠️ Shallow {sp['depth']}m at ({sp['lat']:.3f},{sp['lon']:.3f}) — need {sp['required']}m")
    for d in dng.get('dangers',[]): warns.append(f"🪨 {d['type'].upper()} '{d['name']}' ({d.get('lat',0):.3f},{d.get('lon',0):.3f}) {d['nearest_nm']}NM")

    overall_safe = not lc and dep['safe'] and dng['safe']

    print(f'[v14] {total_nm:.0f}NM | {len(coords)}→{len(simp)}pts | {method} | named={len(named)} | land={lc}',flush=True)

    return jsonify({
        'waypoints':       [{'lat':float(c[1]),'lon':float(c[0])} for c in simp],
        'namedWaypoints':  named,
        'totalNM':         round(total_nm,1),
        'source':          'maritime-router-v14',
        'method':          method,
        'graphNodes':      len(_N),
        'graphEdges':      len(_GE),
        'pointsRaw':       len(coords),
        'pointsFinal':     len(simp),
        'landCrossing':    lc,
        'tssZones':        tss,
        'overallSafe':     overall_safe,
        'warnings':        warns,
        'safetyReport':    {'depth':dep,'danger':dng},
    })

# ══════════════════════════════════════════════════════════════
# /safety-check
# ══════════════════════════════════════════════════════════════
@app.route('/safety-check',methods=['POST','OPTIONS'])
def safety_ep():
    if request.method=='OPTIONS': return jsonify({}),200
    try:
        body=request.get_json(force=True)
        if not body: return jsonify({'error':'JSON required'}),400
        raw=body.get('waypoints',[])
        if len(raw)<2: return jsonify({'error':'Need ≥2 waypoints'}),400
        coords=[[float(w['lon']),float(w['lat'])] for w in raw]
        draft=float(body.get('draft',10.0)); saf=float(body.get('safety',2.0))
        beam=float(body.get('beam',32.0));   loa=float(body.get('loa',200.0))

        lc=any_xland(coords)
        lsegs=[]
        if lc:
            for i in range(len(coords)-1):
                if xland(coords[i],coords[i+1]):
                    lsegs.append({'from':{'lon':coords[i][0],'lat':coords[i][1]},
                                  'to':{'lon':coords[i+1][0],'lat':coords[i+1][1]},'seg':i})

        tss=tss_check(coords); dep=depth_check(coords,draft,saf); dng=danger_check(coords)
        tot,ml,legs=0.0,0.0,[]
        for i in range(len(coords)-1):
            c1,c2=coords[i],coords[i+1]; nm=hav(c1[1],c1[0],c2[1],c2[0])
            tot+=nm; ml=max(ml,nm)
            legs.append({'from':{'lon':c1[0],'lat':c1[1]},'to':{'lon':c2[0],'lat':c2[1]},
                         'nm':round(nm,1),'bearing':round(brg(c1[0],c1[1],c2[0],c2[1]),1)})
        warns=[]
        if lc: warns.append(f'🚨 LAND CROSSING in {len(lsegs)} segment(s)')
        for z in tss: warns.append(f'🚢 TSS: {z}')
        for sp in dep.get('shallow',[]): warns.append(f"⚠️ Shallow {sp['depth']}m at ({sp['lat']:.3f},{sp['lon']:.3f})")
        for d in dng.get('dangers',[]): warns.append(f"🪨 {d['type']} '{d['name']}' {d['nearest_nm']}NM")
        eta=lambda nm,kn:round(nm/kn,2) if kn>0 else None
        return jsonify({
            'overall_safe':not lc and dep['safe'] and dng['safe'],
            'total_warnings':len(warns),'warnings':warns,
            'route_stats':{'total_nm':round(tot,1),'waypoint_count':len(coords),
                           'max_leg_nm':round(ml,1),
                           'eta':{'10kn':eta(tot,10),'12kn':eta(tot,12),'14kn':eta(tot,14),'15kn':eta(tot,15),'18kn':eta(tot,18)}},
            'land_check':{'safe':not lc,'problem_segments':lsegs},
            'tss_check':{'zones_found':len(tss),'zones':tss},
            'depth_check':{'safe':dep['safe'],'min_depth_m':dep.get('min_depth'),'required':dep.get('required'),'shallow':dep.get('shallow',[])},
            'danger_check':{'safe':dng['safe'],'dangers':dng.get('dangers',[])},
            'vessel_params':{'draft_m':draft,'safety_m':saf,'beam_m':beam,'loa_m':loa},
            'legs':legs,
        })
    except Exception as ex:
        print(f'[safety] {ex}',file=sys.stderr); return jsonify({'error':str(ex)}),500

