@app.route('/graph/nodes')
def gnodes():
    named=[{'id':i,'name':n['name'],'lat':n['lat'],'lon':n['lon']} for i,n in _N.items() if n['name']]
    return jsonify({'total_nodes':len(_N),'named_nodes':len(named),'nodes':named})

